// Tailwind CSS
function Card() {
  return (
    <div className="bg-white rounded-lg shadow-md p-6 hover:shadow-lg transition">
      <h2 className="text-xl font-bold text-gray-800 mb-2">Title</h2>
      <p className="text-gray-600">Content</p>
    </div>
  );
}

// postcss.config.js
module.exports = {
  plugins: {
    'postcss-px-to-viewport': {
      viewportWidth: 750,
      unitPrecision: 5,
      viewportUnit: 'vw',
      minPixelValue: 1
    },
    autoprefixer: {}
  }
};

// 媒体查询
